  Stage_118137_Name = {
    Text = "\"ParaísoN.º\""
  },
  Stage_118138_Desc = {
    Text = "\"No digo cuán noble es mi amor, solo que pensar en ti me hace dormir pacíficamente por la noche.\""
  },
  Stage_118138_Name = {Text = "Forastero"},
  Stage_118139_Desc = {
    Text = "La santa se erguía en el altar, mirando las llamas que ardían con fuerza. \n Las lenguas de fuego que danzaban en sus ojos no reflejaban miedo, sino el destino que finalmente había llegado. \n Podía escuchar el crujido de la leña y el eco de la profecía que se desvanecía en su interior. \n En ese momento, ya no era una prisionera atada."
  },
  Stage_118139_Name = {
    Text = "Ceremonia de pilotaje"
