  Stage_123112_Desc = {
    Text = "La niebla cubre mis ojos, haciendo que pierda la conexión con mi propio mundo, pero a través de tus ojos, veo el pasado al que nunca podré regresar, las personas que nunca volveré a ver. \n Somos similares."
  },
  Stage_123112_Name = {
    Text = "A través de tus ojos"
  },
  Stage_123113_Desc = {
    Text = "La niebla cubre mis ojos, haciendo que pierda la conexión con mi propio mundo, pero a través de tus ojos, veo el pasado al que nunca podré regresar, las personas que nunca podré volver a encontrar. \n Somos similares."
