  Stage_131105_Desc = {
    Text = [[
La jaula inmortal es tejida por las propias manos de los prisioneros.
Tejen por la eternidad. Nunca han escapado.]]
  },
  Stage_131105_Name = {Text = "Capullo"},
  Stage_132466_Desc = {
    Text = "Exclusivo para pruebas internas"
  },
  Stage_132466_Name = {
    Text = "Entorno de prueba · Capítulo del Olvido"
  },
  Stage_139577_Desc = {
    Text = "Genial, estos... no no no, quiero decir que estos gatos negros son absolutamente terribles!"
  },
  Stage_139577_Name = {
    Text = "Fiebre del Oro Negro"
  },
  Stage_139578_Desc = {
    Text = "Con los bolsillos llenos de Plata y Rosa Dorada, el general victorioso regresa a casa cargado de botín."
  },
  Stage_139578_Name = {
    Text = "Regresar con carga completa"
  },
  Stage_139579_Desc = {
    Text = "Has puesto la mira en el gato más grande de todos. Y él ha puesto la mira en ti."
  },
  Stage_139579_Name = {
    Text = "El Gato Más Grande"
  },
  Stage_139580_Desc = {
    Text = "Pero aún quedan tantos gatos. Vamos... ¿una última vez?"
  },
  Stage_139580_Name = {
    Text = "hazlo de nuevo"
  },
  Stage_139581_Desc = {
    Text = "Cuando el primer destello de plata brilla sobre el mar negro como la brea, tu red para atrapar gatos se balancea con renovada fuerza."
  },
  Stage_139581_Name = {
    Text = "Primer Cubo de Plata"
  },
  Stage_139582_Desc = {
    Text = "Los gatos negros están contraatacando—eso significa que estás haciendo algo bien."
  },
  Stage_139582_Name = {
    Text = "Resistencia al Arresto"
  },
  Stage_139583_Desc = {
    Text = "Red más grande, más gatos—y los grandes necesitan una red grande. ¡Atrápalos a todos!"
  },
  Stage_139583_Name = {
    Text = "¡Atrápalos a Todos!"
  },
  Stage_140299_Desc = {
    Text = "Florece, y danza.\nHas decidido que sin importar cuán peligroso sea el camino por delante, nunca soltarás su mano.\nEn el momento en que nos separemos, deja que el mundo invertido se llene de lo \"real\"."
  },
  Stage_140299_Name = {Text = "Adiós"},
  Stage_140300_Desc = {
    Text = "La memoria es como una semilla—contiene todas las cosas, pero no revela nada.\nHasta que el riego la hace echar raíces y brotar, hasta que la tierra la abraza, permitiéndole extraer fuerza de la realidad."
  },
  Stage_140300_Name = {Text = "\"Recordar\""},
