  Stage_141275_Name = {
    Text = "Dualismo·Locura"
  },
  Stage_141276_Desc = {
    Text = "El tiempo borrará la mayoría de las cosas; a veces, ellos llorarán brevemente, y luego todo como de costumbre.\nY en muy pocas ocasiones — cuando la suerte no acompaña.\nTe encontrarás con un paranoico que no se detiene ante nada."
  },
  Stage_141276_Name = {
    Text = "Cuando Te Fuiste"
  },
  Stage_141278_Desc = {
