  Stage_146928_Desc = {
    Text = "Una princesa en apuros rescatada por un caballero, una historia tradicional conocida por todos."
  },
  Stage_146928_Name = {Text = "Princesa"},
  Stage_146929_Desc = {
    Text = "El dragón despierta y el odio vuelve a encenderse. El aliento de la bestia brota entre las rocas, el veneno de la guerra arde con furia, sin extinguirse hasta hoy.\nLa tierra retumba con un trueno ensordecedor."
  },
  Stage_146929_Name = {
    Text = "Guarida del Dragón"
  },
  Stage_146930_Desc = {
    Text = "El caballero se adentró en caminos desconocidos, atravesó páramos yermos y colinas, con solo su sombra como compañía.\nQuizás ya había muerto, pero sin testigos, también lo olvidó.\nEl mundo es tan silencioso."
  },
  Stage_146930_Name = {Text = "Túmulo"},
  Stage_146931_Desc = {
    Text = "Cuarenta días y cuarenta noches de lluvia cayeron sobre la tierra; no podemos continuar, y aun así continuaremos."
  },
  Stage_146931_Name = {
    Text = "Isla Manzana"
  },
  Stage_146932_Desc = {
    Text = "El dragón despierta y el odio vuelve a encenderse. El aliento de la bestia brota entre las rocas, el veneno de la guerra arde con furia, sin extinguirse hasta hoy.\nLa tierra retumba con un trueno ensordecedor."
  },
  Stage_146932_Name = {
    Text = "Guarida del Dragón"
  },
  Stage_146933_Desc = {
    Text = "Esas son las raíces y las flores del jardín del paraíso, la corona de todos los deseos del mundo, una abundancia que jamás se agota.\nBebe el vino de la copa y verás aquello que más anhelas."
  },
  Stage_146933_Name = {
    Text = "Cáliz Sagrado"
  },
  Stage_146934_Desc = {
    Text = "El dragón despierta y el odio vuelve a encenderse. El aliento de la bestia brota entre las rocas, el veneno de la guerra arde con furia, sin extinguirse hasta hoy.\nLa tierra retumba con un trueno ensordecedor."
  },
  Stage_146934_Name = {
    Text = "Guarida del Dragón"
  },
