  Stage_24183_Name = {
    Text = "Nivel de Prueba Dama Roja"
  },
  Stage_24184_Name = {
    Text = "Nivel de demostración de la Flor de Lodo"
  },
  Stage_24423_Desc = {
    Text = "Ningún ciudadano de Londinium rechazaría un té caliente recién preparado.\nIncluso si es una taza de té oolong de lamprea."
  },
  Stage_24423_Name = {
    Text = "Especial de Lampreia"
  },
  Stage_24424_Desc = {
    Text = "Todos los elegidos por el destino creen que son la excepción.\nEl destino se burla de la probabilidad."
  },
  Stage_24424_Name = {
    Text = "Prisionero del Destino"
  },
  Stage_24425_Desc = {
    Text = "Cortar.\nElla prometió romper todos los lazos con su vida anterior.\nTal como cortar una cinta en dos con unas tijeras."
  },
  Stage_24425_Name = {
    Text = "Dedicado a Sorel"
  },
  Stage_24426_Desc = {
    Text = "Una vez más, te conviertes en cautivo de la simpatía, sumergiéndote profundamente en su alma."
  },
  Stage_24426_Name = {
    Text = "Juicio en Caída"
  },
  Stage_24427_Desc = {
    Text = "Al principio de la historia, serás testigo de una magnífica muerte.\nAunque es el comienzo, está lejos de ser el final."
  },
  Stage_24427_Name = {
    Text = "Canción de Bebida"
  },
  Stage_24428_Desc = {
    Text = "El nombre de la chica es Sorel, el orgullo de la aldea.\nObediente y limpia, tiene una apariencia blanca como la nieve y camina con pasos pequeños, como una verdadera dama.\nPero a diferencia de esas damas, nunca sueña."
  },
  Stage_24429_Desc = {
    Text = "La lógica es como el whisky: demasiado de ella pierde su beneficio."
  },
  Stage_24429_Name = {
    Text = "Armonía Enmascarada"
  },
  Stage_24430_Desc = {
    Text = "Bajo Su meticulosa atención, el cáncer de la ambición finalmente se propagó como rosas en flor."
  },
  Stage_24430_Name = {
    Text = "Fiesta Roja"
  },
  Stage_24431_Desc = {
    Text = "Slurp. Slurp.\nNos retorcemos en las sombras, susurramos secretos.\nCuerpos gordos dejan marcas de lágrimas retorcidas a la luz de la luna—saladas, lo sabes."
  },
  Stage_24431_Name = {Text = "Huevo"},
  Stage_24432_Desc = {
    Text = "Scones, macarons y chocolate caliente humeante...\nEl deseo de la criada es simple: comer mejor, y aún más."
  },
  Stage_24432_Name = {
    Text = "Deseo de la Sirvienta"
  },
  Stage_24433_Desc = {
    Text = "Ten cuidado, ten cuidado.\nLa dama que todos admiran no es una verdadera dama.\n¿Pero a quién le importa?"
  },
  Stage_24433_Name = {
    Text = "Guía de la Dama"
  },
  Stage_24434_Desc = {
    Text = [[
La rosa inclina su delgada cabeza ante las campanas, mientras el buitre se pierde entre las flores apestosas.
Nadie canta, nadie habla. El mundo se desvanece con su partida.]]
  },
  Stage_24434_Name = {
    Text = "Funeral de Rose"
  },
  Stage_24435_Desc = {
    Text = "Ella drena los manantiales, matando pájaros inocentes.\nTrae vientos dorados, barriendo los campos como meteoros.\nPrende fuego al mundo con Deseo, luego lo convierte en cenizas."
  },
  Stage_24435_Name = {
    Text = "La Dama de las Camelias"
  },
  Stage_24439_Desc = {
    Text = "Ten cuidado, ten cuidado.\nLa dama que todos admiran no es una verdadera dama.\n¿Pero a quién le importa?"
  },
  Stage_24439_Name = {
    Text = "Guía de la Dama"
  },
  Stage_24440_Desc = {
    Text = "Scones, macarons y chocolate caliente humeante...\nEl deseo de la criada es simple: comer mejor, y aún más."
  },
  Stage_24440_Name = {
    Text = "Deseo de la Sirvienta"
  },
  Stage_24441_Desc = {
    Text = "Al principio de la historia, serás testigo de una magnífica muerte.\nAunque es el comienzo, está lejos de ser el final."
  },
  Stage_24441_Name = {
    Text = "Canción de Bebida"
  },
  Stage_24442_Desc = {
    Text = "La lógica es como el whisky: demasiado de ella pierde su beneficio."
  },
  Stage_24442_Name = {
    Text = "Armonía Enmascarada"
  },
  Stage_24443_Desc = {
    Text = "Todos los elegidos por el destino creen que son la excepción.\nEl destino se burla de la probabilidad."
  },
  Stage_24443_Name = {
    Text = "Prisionero del Destino"
  },
  Stage_24444_Desc = {
    Text = "Slurp. Slurp.\nNos retorcemos en las sombras, susurramos secretos.\nCuerpos gordos dejan marcas de lágrimas retorcidas a la luz de la luna—saladas, lo sabes."
  },
  Stage_24444_Name = {Text = "Huevo"},
  Stage_24445_Desc = {
    Text = "Bajo Su meticulosa atención, el cáncer de la ambición finalmente se propagó como rosas en flor."
  },
  Stage_24445_Name = {
    Text = "Fiesta Roja"
  },
  Stage_24446_Desc = {
    Text = "El nombre de la chica es Sorel, el orgullo de la aldea.\nObediente y limpia, tiene una apariencia blanca como la nieve y camina con pasos pequeños, como una verdadera dama.\nPero a diferencia de esas damas, nunca sueña."
  },
  Stage_24447_Desc = {
    Text = "Una vez más, te conviertes en cautivo de la simpatía, sumergiéndote profundamente en su alma."
  },
  Stage_24447_Name = {
    Text = "Juicio en Caída"
  },
  Stage_24448_Desc = {
    Text = "Una vez más, te conviertes en cautivo de la simpatía, sumergiéndote profundamente en su alma."
  },
