  Stage_35099_Desc = {
    Text = "\"Shh... ¿adivina qué vi a través de tus ojos?\"\nDespués de que Aurita se asustara hasta las lágrimas por el Guardián, Lotan casi derribó la cuarta pared de la habitación del Guardián porque las lágrimas de Aurita eran demasiado perturbadoras."
  },
  Stage_35099_Name = {
    Text = "IX· La cuarta pared del teatro"
  },
  Stage_35100_Desc = {
    Text = "\"No dejes que la audiencia se sumerja por completo en la trama; haz que analicen y critiquen lo que está sucediendo en el escenario.\"\nRespecto a esta teoría, Aurita comentó: ¡Aurita no quiere ser regañada por nadie! ¡Aurita solo quiere ser buena amiga de todos!"
  },
  Stage_35100_Name = {
    Text = "VIII· Efecto de extrañamiento"
  },
  Stage_35129_Desc = {
    Text = "Ella es el límite donde los sueños y la realidad se entrelazan, el reflejo profundo dentro de cada alma que contempla el cielo nocturno."
  },
  Stage_35129_Name = {
    Text = "Estrellas retorcidas"
  },
  Stage_35129_StageInitStateText = {
    Text = "Pesadilla Marina"
  },
  Stage_35130_Desc = {
    Text = "Ella está lista."
  },
  Stage_35130_Name = {
    Text = "Llama internalizada"
  },
  Stage_35571_Desc = {
    Text = "Porque eres amiga de Aurita, ella quiere presentarte a todos sus amigos."
  },
  Stage_35571_Name = {
    Text = "Colección de Amigos Grandes"
  },
  Stage_35572_Desc = {
    Text = "Porque eres amiga de Aurita, ella quiere presentarte a todos sus amigos."
  },
  Stage_35572_Name = {
    Text = "Colección de Amigos Grandes"
  },
  Stage_35573_Desc = {
    Text = "Porque eres amiga de Aurita, ella quiere presentarte a todos sus amigos."
  },
  Stage_35573_Name = {
    Text = "Colección de Amigos Grandes"
  },
  Stage_35574_Desc = {
    Text = "Aurita te quiere y desea que te conviertas en un amigo que pueda unirse a ella en un día ordinario."
  },
  Stage_35574_Name = {
    Text = "Día Silencioso"
  },
  Stage_35575_Desc = {
    Text = "Con todos al lado de Aurita, Aurita no tiene miedo de quedarse dormida en absoluto."
  },
  Stage_35575_Name = {
    Text = "Palacio en el agua"
  },
  Stage_35843_Name = {
    Text = "Nivel de Prueba de Dama Aequor"
  },
  Stage_35857_Desc = {
    Text = "Las estrellas han ido donde pertenecen, comunicándose de maneras que van más allá de la comprensión humana, tejiendo una red invisible que captura el flujo del tiempo y la luz de años pasados."
  },
  Stage_35857_Name = {
    Text = "Camino astral desconocido"
  },
  Stage_36125_Desc = {
    Text = "El niño no bendecido canta himnos en el mar.\nShh... Mantente en silencio. No perturbe su sueño."
  },
  Stage_36125_Name = {
    Text = "Canto del Feto Sagrado II"
  },
  Stage_36125_StageInitStateText = {
