  Stage_36614_Desc = {
    Text = "Entregándose a la lujuria, cediendo a los deseos...\n—¿Y luego?\nEnfréntate a las llamas eternas como advertencia.\n—Oh."
  },
  Stage_36614_Name = {
    Text = "Noche de muerte, hidromiel y canciones"
  },
  Stage_36615_Desc = {
    Text = "Cuatro matrimonios y cuatro funerales: estos se convirtieron en las únicas notas al pie de la \"vida emocional\" de Wanda en el reino mortal."
  },
  Stage_36615_Name = {
    Text = "Cuatro bodas"
  },
  Stage_36616_Desc = {
