  Stage_36619_Name = {
    Text = "Noche de muerte, hidromiel y canciones"
  },
  Stage_36620_Desc = {
    Text = "La reina se sienta en su alto trono.\nAcompañada de tesoros interminables, riqueza, y un rastro de hundidos restos cósmicos."
  },
  Stage_36620_Name = {
    Text = "Reina marginada"
  },
  Stage_36621_Desc = {
    Text = "Antes de Clades, la capital era una extensión de su ambición y deseo.\nDespués de Clades, la capital se convirtió en una prisión de noche y soledad."
  },
  Stage_36621_Name = {Text = "Piper"},
  Stage_36887_Name = {
    Text = "Nivel de juicio: Reina de las espinas"
  },
  Stage_38756_Desc = {
    Text = "Ella cierra los ojos y flota sin rumbo en el vacío del universo.\nUn año, cien años... Finalmente, un día, se dice a sí misma: \"Está bien. Déjame definir la verdad y la falsedad.\"\nLa reina y su ciudad inmortal—Isalaw, así permanecen suspendidas en medio de la vasta galaxia del universo.\nElla comparte la historia de Isalaw conmigo para que sea eternamente recordada."
  },
  Stage_38756_Name = {
    Text = "Un Fragmento de Memoria: Reminiscencia VI"
