  Stage_44200_Name = {
    Text = "Arrepentimiento · Crecimiento II"
  },
  Stage_44201_Desc = {
    Text = "Tontos, encendieron las llamas, quemando la esperanza y la redención hasta convertirlas en cenizas.\n¿Cómo sabe esta llamada justicia mientras luchas en la muerte negra como el ébano?"
  },
  Stage_44201_Name = {
    Text = "Arrepentimiento · Crecimiento III"
  },
  Stage_44202_Desc = {
    Text = "Su miedo a la enfermedad los deja inquietos.\n\"¿Por qué sólo lo bendices a él? ¡Yo también estoy enfermo!\"\n\"¡Soy el más enfermo, debería ser el primero en recibir una bendición!\""
  },
  Stage_44202_Name = {
    Text = "Competir · Crecimiento IV"
  },
  Stage_44203_Desc = {
    Text = "Solo lo que les beneficia se considera bueno; cualquier bendición que no les llegue es una maldición.\n\"¿Qué bendición? ¡Claramente es sangre maldita!\"\n\"¡Esto debe ser brujería! ¡Es un demonio!\""
  },
  Stage_44203_Name = {
    Text = "Acusar·Crecimiento II"
  },
  Stage_44204_Desc = {
    Text = "Se niegan a entender, a aceptar.\nSu mundo es solo blanco y negro, aunque ni siquiera ellos pueden definirlo.\n\"¡Quémalo, quémalo!\"\n\"¡Quema a este obispo hereje! ¡Que el mal perezca!\""
  },
  Stage_44204_Name = {
    Text = "Paranoia·Crecimiento III"
  },
