  Stage_46550_Name = {
    Text = "Amígdala · Emergencia III"
  },
  Stage_46551_Desc = {
    Text = "En el año 315 de la Era Hongji, el 2 de diciembre, fue declarada intangible.\nGritó fuertemente, pero nadie respondió; robó pan, pero no fue atrapada ni encarcelada.\nUna enfermedad conocida como Olvido infectó a todos, dejándola como la única excepción."
  },
