  Stage_53791_Name = {
    Text = "Juego de Muñecos·Episodio 4"
  },
  Stage_53792_Desc = {
    Text = "Ella seguirá las indicaciones del guion para realizar un acto tras otro, provocando un caos interminable.\nY ella es la bailarina que vuela con gracia en el ojo de la tormenta.\nSiempre ha sido la actriz más dedicada."
  },
