  Stage_53797_Name = {
    Text = "Guion sin terminar · Parte 3"
  },
  Stage_53798_Desc = {
    Text = "Su tío de piernas largas era diferente: estaba hecho de niebla.\nComo la chica había perdido la fe en los humanos, ya sea niebla, oro o símbolos, nada de eso le importaba.\nPor supuesto, eventualmente pagaría por este error de juicio—pero esa es una historia para otro momento."
  },
