  Stage_54558_Desc = {
    Text = "Hoy, Lemuria dará la bienvenida a un nuevo rey.\n\nA partir de ahora, todos los desastres naturales se retirarán."
  },
  Stage_54558_Name = {Text = "Nuevo rey"},
  Stage_54804_Desc = {
    Text = "\"Como narrador, soy el asesino\"— Un truco tan cliché, desprovisto de cualquier arte o habilidad.\nDesafortunadamente, me topé con él una vez más."
  },
