  Stage_56876_Desc = {
    Text = "Hay una estrella suspendida en una noche viscosa. \nLa estrella se expande, brilla y se convierte en un malvavisco infinitamente grande. \nEsto es el amor y el odio acumulados durante toda una vida. Pruébalo, ¿a qué sabe?"
  },
  Stage_56876_Name = {
    Text = "Estrellas · Parte 6"
  },
  Stage_56877_Desc = {
    Text = "Hay una estrella suspendida en una noche densa. \n La estrella se expande, brilla y se convierte en un malvavisco infinitamente grande. \n Es el amor y el odio acumulados durante toda una vida. ¿Quieres probarlo? ¿Qué sabor tiene?\n\n?"
  },
  Stage_56877_Name = {
    Text = "Estrellas · Parte 5"
  },
  Stage_56878_Desc = {
    Text = "Una estrella cuelga en la noche viscosa.\nLa estrella se expande, brilla y se convierte en un algodón de azúcar infinitamente grande.\nEs el amor y el odio acumulados durante toda una vida. Pruébalo, ¿a qué sabe?"
  },
