  Stage_56888_Desc = {
    Text = "Bienvenido a la Casa de las Muñecas, aquí hay mil sonrisas idénticas.\n¡Ja, ja! ¿Cuál de ellas fue tu amiga en el pasado?"
  },
  Stage_56888_Name = {
    Text = "Casa de la muñeca · Parte I"
  },
  Stage_56889_Desc = {
    Text = "Bienvenido a la Casa de las Muñecas, aquí hay mil sonrisas idénticas. \n¡Ja, ja! ¿Cuál de ellas es tu antiguo amigo?"
  },
  Stage_56889_Name = {
    Text = "Casa de la muñeca·Parte III"
  },
  Stage_56890_Desc = {
    Text = "Bienvenido a la Casa de las Muñecas, aquí hay mil sonrisas idénticas. \nJi, ji, ¿cuál de ellas fue tu amiga en el pasado?"
  },
  Stage_56890_Name = {
