  Stage_58364_StageInitStateText = {Text = "Primordial"},
  Stage_58365_Desc = {
    Text = "\"No me queda nada.\" dijo el niño de la calle de un ojo, \"Solo esta flor para ofrecerte, gran reina.\"\nElla tomó la fresia blanca pero se sintió confundida. Parecía que esta escena se había repetido innumerables veces en las profundidades de su memoria.\nRepetidamente, como el laberinto que atrapó al Minotauro."
  },
