  },
  Stage_59066_Name = {Text = "Restos"},
  Stage_59067_Desc = {
    Text = "Oculto bajo Mitag está la primera y también la última catástrofe del mundo."
  },
  Stage_59067_Name = {
    Text = "Fisura Prime I"
  },
  Stage_59068_Desc = {
