  Stage_7635_Desc = {
    Text = [[
Son como sorcerers esquivos, flotando en las grietas del tiempo y el espacio.
Sin odio, sin miedo, sin piedad.]]
  },
  Stage_7635_Name = {
    Text = "Posimagen Dimensional II"
  },
  Stage_7636_Desc = {
    Text = "Ella lleva el relicario sagrado, guía a los fieles con doctrina y esparce la fe con colmillos venenosos."
  },
  Stage_7636_Name = {
    Text = "Agarrón Devoto III"
  },
  Stage_7637_Desc = {
    Text = "Existieron mucho antes de que nacieran las estrellas.\nSon tanto Ilusión como todo."
  },
  Stage_7637_Name = {
    Text = "Rastro Turbio V"
  },
  Stage_7638_Desc = {
    Text = "Custodian en silencio los secretos del océano, con almas tan profundas como el cosmos."
  },
  Stage_7638_Name = {
    Text = "Rastro Abismal V"
  },
  Stage_76399_Desc = {
