  Stage_7679_Name = {
    Text = "Inmersión en sueños VI"
  },
  Stage_7680_Desc = {
    Text = "Oh, brazos, ¡esos molestos brazos! Siguen tirando de mi cabello."
  },
  Stage_7680_Name = {
    Text = "Veinticuatro"
  },
  Stage_7681_Desc = {
    Text = "¡Splash, está agrietado!\n¡Splash, está roto!"
  },
  Stage_7681_Name = {
    Text = "Casa de Muñecas"
  },
  Stage_7682_Desc = {
    Text = "Claro, cariño. Llora todo lo que quieras y enmarca tu dolor como una obra maestra."
  },
  Stage_7682_Name = {
    Text = "Doncella y lágrimas"
  },
  Stage_7683_Desc = {
    Text = "Claro, claro. Los ojos son la prisión de la mente, y el alma es la cadena que ata al cuerpo."
  },
  Stage_7683_Name = {
    Text = "Melancolía anatómica"
  },
  Stage_7684_Desc = {
    Text = "Dulce, rico y amado por los niños.\nElegante, sublime y deseado por los adultos."
  },
  Stage_7684_Name = {
    Text = "Arte empalagoso"
  },
  Stage_76854_Desc = {
    Text = "Desastres invisibles renacen, mientras la realidad y el pasado del mundo físico se desploman al abismo."
