    Text = "Zona de Desastre·Ola 1·Alerta IV"
  },
  Stage_77087_Desc = {
    Text = "Desastres invisibles renacen, mientras la realidad y el pasado del mundo físico se desploman al abismo."
  },
  Stage_77087_Name = {
    Text = "Zona de Desastre·Ola 3·Alerta IV"
  },
  Stage_77088_Desc = {
    Text = "Desastres invisibles renacen, mientras la realidad y el pasado del mundo físico se desploman al abismo."
  },
  Stage_77088_Name = {
    Text = "Zona de Desastre·Ola 2·Alerta IV"
  },
  Stage_77089_Desc = {
    Text = "La Marea Negra atraviesa la frontera de alarma, y hasta las mínimas olas anuncian un peligro capaz de devorar a los descuidados."
  },
  Stage_77089_Name = {
    Text = "Zona de Desastre·Ola 2·Alerta I"
  },
  Stage_7708_Desc = {
    Text = "¡No mires atrás! Tan valioso consejo. No sigas los pasos de Orfeo."
  },
  Stage_7708_Name = {
    Text = "No mires atrás"
  },
  Stage_77090_Desc = {
