  Stage_7710_Desc = {
    Text = [[
Los diarios son fragmentos de memoria.
Los diarios siempre se descubren durante las investigaciones.]]
  },
  Stage_7710_Name = {
    Text = "Fragmento de memoria"
  },
  Stage_7711_Desc = {
    Text = "Este es un reino creado para ella, que encarna tanto el amor profundo como una jaula aterradora."
  },
  Stage_7711_Name = {Text = "Asilo"},
  Stage_7712_Desc = {
    Text = "Cuando los nobles pierden su poder y los ricos pierden sus fortunas, se encuentran indefensos, tal como lo estás ahora."
  },
  Stage_7712_Name = {
    Text = "Asilo del Cuco"
  },
  Stage_7713_Desc = {
    Text = "El conflicto en este mundo no se limita a las batallas en el campo de batalla; a veces, se puede encontrar en las palabras de los locos."
  },
  Stage_7713_Name = {
    Text = "Boca del loco"
  },
  Stage_7714_Desc = {
    Text = "Entretejido en la niebla, innumerables pasos avanzan, cada paso cuestionando el destino."
  },
  Stage_7714_Name = {
    Text = "Camino desviado"
  },
  Stage_7715_Desc = {
    Text = "La llama que arde silenciosamente hace promesas vacías a los viajeros."
  },
  Stage_7715_Name = {
    Text = "Fuego que atrapa polillas"
  },
  Stage_7716_Desc = {
    Text = "Ofrece la realidad forjada de Caro, un Abismo insaciable."
  },
  Stage_7716_Name = {
    Text = "Residuos Orgánicos V"
  },
  Stage_7717_Desc = {
    Text = "La tormenta todavía está en gestación; aún no ha terminado."
  },
  Stage_7717_Name = {
    Text = "Reinicio de la realidad"
  },
  Stage_7718_Desc = {
    Text = "Navega hacia la tierra, hacia un destello de esperanza."
  },
  Stage_7718_Name = {
    Text = "Embarque trágico"
  },
  Stage_7719_Desc = {
    Text = "No era una vida que se esperara, simplemente un parásito asqueroso."
  },
  Stage_7719_Name = {Text = "Parásito"},
  Stage_7720_Desc = {
    Text = "Persiguiendo la luz seductora en la noche interminable, como una polilla atraída por la llama, ascendiendo hacia el fuego del destino."
  },
  Stage_7720_Name = {
    Text = "Polilla de pira"
  },
  Stage_7721_Desc = {
    Text = "La noche es erosionada por corrientes oscuras, y las estrellas caen en silencio. Un mes de crisis, lleno de giros y tormentas, refleja en silencio un futuro desconocido."
  },
  Stage_7721_Name = {
    Text = "Luna de Crisis"
  },
  Stage_7722_Desc = {
    Text = "Tiembla y lucha en la tormenta del destino, pero nunca se alejará realmente."
  },
  Stage_7722_Name = {Text = "Precipicio"},
  Stage_7723_Desc = {
    Text = "Las amistades que han resistido el paso del tiempo han dado lugar a una nueva esperanza."
  },
  Stage_7723_Name = {
    Text = "Viejos lazos, nuevos"
  },
  Stage_7724_Desc = {
    Text = "Su reino es la concha del universo, y Sus deseos son ilimitados."
  },
  Stage_7724_Name = {
    Text = "La Guarida de los Gusanos III"
  },
  Stage_7725_Desc = {
    Text = "Ofrece la realidad forjada de Caro, un Abismo insaciable."
  },
  Stage_7725_Name = {
    Text = "Residuos Orgánicos II"
  },
  Stage_7726_Desc = {
    Text = "Eran originalmente una mezcla inconsciente de tristeza, distorsión y ingenuidad,\ndonde estaban disfrazados como niños alegres, adultos y mascotas.\nNunca habiendo experimentado el sabor de la felicidad, se convirtieron en los peores actores."
  },
  Stage_7726_Name = {
    Text = "El Secreto de la Escultura de Cera I"
  },
  Stage_7727_Desc = {
    Text = "Se apoya contra la cama con una postura tímida, sus ojos de botón apagados mirando al vacío.\nEl pequeño cuerpo lleva las lágrimas de su dueño pero no puede ofrecer palabras de consuelo."
  },
  Stage_7727_Name = {
    Text = "Lágrimas de la Muñeca I"
  },
  Stage_7728_Desc = {
    Text = "\"Es Único, es Todo, es la esperanza que abre la puerta a la verdad.\" Incontables llaves forman un círculo. Caen del cielo, trayendo a la gente una esperanza opresiva. Trayendo también una pesada tumba."
  },
  Stage_7728_Name = {
    Text = "Inmersión en sueños I"
  },
  Stage_7729_Desc = {
    Text = "\"Es Único, es Todo, es la esperanza que abre la puerta a la verdad.\" Incontables llaves forman un círculo. Caen del cielo, trayendo a la gente una esperanza opresiva. Trayendo también una pesada tumba."
  },
