  },
  Stage_7765_Desc = {
    Text = "El primer paso para convertirte en un genio farmacólogo."
  },
  Stage_7765_Name = {
    Text = "Dominio de Pócimas I"
  },
  Stage_7766_Desc = {
    Text = "Aleatorio 2"
  },
  Stage_7766_Name = {
    Text = "Espejo de los Pantanos de la Luna II"
  },
