  Stage_7897_Desc = {
    Text = "El ídolo en ruinas observa a su pueblo. Viendo cómo sobreviven, se reproducen y luchan; para finalmente ser olvidado. El ídolo en ruinasañora a su gente."
  },
  Stage_7897_Name = {
    Text = "Inmersión en sueños VII"
  },
  Stage_7898_Desc = {
    Text = "En la densa neblina que envuelve el albergue, toca, corta, desvanece y muere."
  },
  Stage_7898_Name = {
    Text = "¿Quién mató al petirrojo?"
  },
  Stage_7899_Desc = {
    Text = "La enfermedad que devasta aquí no es una enfermedad ordinaria."
  },
  Stage_7899_Name = {Text = "Malestar"},
  Stage_7900_Desc = {
    Text = "Tú y Ramona se dirigieron al distrito este de Londinium, al orfanato Lillian, para su primera investigación como nuevos Guardianes.\nTodo saldrá bien, ¿verdad?"
  },
  Stage_7900_Name = {
    Text = "No juzgues a un libro por su portada"
  },
  Stage_7901_Desc = {
    Text = "El peso de la conciencia es igual al de un voto."
  },
  Stage_7901_Name = {
    Text = "Peso de la conciencia"
  },
  Stage_7902_Desc = {
    Text = "Dulce, rico y amado por los niños.\nElegante, sublime y deseado por los adultos."
  },
  Stage_7902_Name = {
    Text = "Arte empalagoso"
  },
  Stage_7903_Desc = {
    Text = "Deseo no tener que crecer, pasando cada día observando las estrellas contigo.\nDeseo poder crecer más rápido para poder proteger a todos ustedes."
  },
  Stage_7903_Name = {
    Text = "Nuestro secreto"
  },
  Stage_7904_Desc = {
    Text = "El peligro viene de dentro."
  },
  Stage_7904_Name = {
    Text = "Peligro interno"
  },
  Stage_7905_Desc = {
    Text = "\"Puerta\"ha sido abierta, la ilusión pronto despertará.\nShh... No mires, no escuches."
  },
  Stage_7905_Name = {
    Text = "Marsh de Caro: Fisura Rotativa IV"
  },
  Stage_7906_Desc = {
    Text = "\"Puerta\"ha sido abierta, la ilusión pronto despertará.\nShh... No mires, no escuches."
  },
  Stage_7906_Name = {
    Text = "Marsh de Caro: Fisura Rotativa IV"
  },
  Stage_7907_Desc = {
    Text = "\"Puerta\"ha sido abierta, la ilusión pronto despertará.\nShh... No mires, no escuches."
  },
  Stage_7907_Name = {
    Text = "Marsh de Caro: Fisura Rotativa IV"
  },
  Stage_7908_Desc = {
    Text = "Corta los hilos de la muñeca, y ella nunca volverá a bailar."
  },
  Stage_7908_Name = {
    Text = "Noche sin aves"
  },
  Stage_7909_Desc = {
    Text = "Ramona se reincorporó al equipo. El viaje del Investigador Mythag continuó."
  },
  Stage_7909_Name = {
    Text = "Ayer otra vez"
  },
  Stage_7910_Desc = {
    Text = "Todo lo que quieres saber está justo ante tus ojos, pero nunca lo has notado."
  },
  Stage_7910_Name = {
    Text = "Debajo del alero"
  },
  Stage_7911_Desc = {
    Text = "Te deseo un agradable viaje."
  },
  Stage_7911_Name = {Text = "Buen viaje"},
  Stage_7912_Desc = {
    Text = "Las piernas humanas no pueden igualar la agilidad de los cuadrúpedos salvajes, pero la mente puede. Sin embargo, después de capturar al \"Sabueso infernal\", ¿qué te espera a continuación?"
  },
  Stage_7912_Name = {
    Text = "As en la manga"
  },
  Stage_7913_Desc = {
    Text = "Las interacciones con la Dama Narciso son siempre transaccionales. La Dama Narciso aparece y propone un trato, pero ¿los misteriosos atacantes aceptarán esta transacción?"
  },
  Stage_7913_Name = {
    Text = "Intercambio justo"
  },
  Stage_7914_Desc = {
    Text = "En el metro, fuiste atacado por misteriosos asesinos..."
  },
  Stage_7914_Name = {
    Text = "Los sin amigos"
  },
  Stage_7915_Desc = {
    Text = "Siguiendo los rumores del sabueso infernal \"Cerbero\", los Investigadores de Mythag llegan a las afueras de un pequeño pueblo llamado Rye cerca de Londinium, explorando los secretos detrás de las desapariciones..."
  },
  Stage_7915_Name = {
    Text = "Piensa antes de actuar"
  },
  Stage_7916_Desc = {
    Text = "El tono de locura y el fuerte hedor, esta es la bienvenida de Rai."
  },
  Stage_7916_Name = {
    Text = "Bienvenido a centeno"
  },
  Stage_7917_Desc = {
    Text = "Buenas noticias y malas noticias. Las pistas perdidas no volverán a aparecer, pero nuevos casos están surgiendo en las sombras. Confíen en mí, los investigadores no se quedarán con las manos vacías de nuevo."
  },
  Stage_7917_Name = {
    Text = "Buenas noticias, malas noticias"
  },
  Stage_7918_Desc = {
    Text = "Aquí yacen las ruinas de una ciudad antigua.\nDescansa como su maestro."
  },
  Stage_7918_Name = {
    Text = "Ruinas de Ponape IV"
  },
  Stage_7919_Desc = {
    Text = "Elworth está ubicado en el polo de Kadath, cubierto de hielo y nieve perenne.\nBajo la gruesa y dura capa de hielo, se puede detectar débilmente la pulsación de la vida."
  },
  Stage_7919_Name = {
    Text = "Cumbres Caóticas III"
  },
  Stage_7920_Desc = {
    Text = "Aquí yace enterrada una universidad, herida y agotada. Durante un tiempo entregó esperanza y coraje para la supervivencia humana .En cuanto al desenlace, lo estas presenciando."
  },
  Stage_7920_Name = {
    Text = "Inmersión en sueños VII"
  },
  Stage_7921_Desc = {
    Text = "Se retuercen y se fusionan en la oscuridad, luego son cuidadosamente almacenados en los ídolos.\nEsta es una reunión largamente esperada."
  },
  Stage_7921_Name = {
    Text = "Marsh de Caro: Fisura I"
  },
  Stage_7922_Desc = {
    Text = "Ofrece la realidad forjada de Caro, un Abismo insaciable."
  },
  Stage_7922_Name = {
    Text = "Residuos Orgánicos IV"
  },
  Stage_7923_Desc = {
    Text = "El Museo de Cera de Rogers está ubicado en lo profundo de la Calle Southwark, cerca de un afluente del Támesis.\nEs modesto, pero atrae a muchos entusiastas del arte vanguardista."
  },
  Stage_7923_Name = {
    Text = "Museo de Cera Loco IV"
  },
