  Stage_7944_Name = {
    Text = "Inmersión en sueños III"
  },
  Stage_7945_Desc = {
    Text = "Ella es el límite donde los sueños y la realidad se entrelazan, el reflejo profundo dentro de cada alma que contempla el cielo nocturno."
  },
  Stage_7945_Name = {
    Text = "Estrellas retorcidas"
  },
  Stage_7945_StageInitStateText = {
    Text = "Pesadilla Marina"
  },
  Stage_7946_Desc = {
    Text = [[
El horizonte curvado escondido en lo profundo del universo.
Puede llevarte de una oscuridad a otra.]]
  },
  Stage_7946_Name = {
    Text = "Garganta de Schwarzschild I"
  },
  Stage_7947_Desc = {
    Text = "La \"Puerta\" está a punto de abrirse, revelando un atisbo de la verdad.\nNo es ni negra ni blanca, la verdad es colorida pero turbia."
  },
  Stage_7947_Name = {
    Text = "Reino del Caos·Fisura III"
  },
  Stage_7948_Desc = {
    Text = "Aquí yacen las ruinas de una ciudad antigua.\nDescansa como su maestro."
  },
  Stage_7948_Name = {
    Text = "Ruinas de Ponape V"
  },
  Stage_7949_Desc = {
    Text = "Se apoya contra la cama con una postura tímida, sus ojos de botón apagados mirando al vacío.\nEl pequeño cuerpo lleva las lágrimas de su dueño pero no puede ofrecer palabras de consuelo."
  },
  Stage_7949_Name = {
    Text = "Lágrimas de la Muñeca II"
  },
  Stage_7950_Desc = {
    Text = "Por tu vida y salud, mantente alejado de la nicotina."
  },
  Stage_7950_Name = {
    Text = "Humo y violeta"
  },
  Stage_7951_Desc = {
    Text = "Estatuas misteriosas vagan y tiemblan en la oscuridad.\nBailan al ritmo de antiguas melodías, guiadas por flautistas distantes."
  },
  Stage_7951_Name = {
    Text = "Marsh de Caro: Fisura II"
  },
  Stage_7952_Desc = {
    Text = "Ofrece la realidad forjada de Caro, un Abismo insaciable."
  },
  Stage_7952_Name = {
    Text = "Residuos Orgánicos III"
  },
  Stage_7953_Desc = {
    Text = "El ídolo en ruinas observa a su pueblo. Viendo cómo sobreviven, se reproducen y luchan; para finalmente ser olvidado. El ídolo en ruinasañora a su gente."
  },
  Stage_7953_Name = {
    Text = "Inmersión en sueños III"
  },
  Stage_7954_Desc = {
    Text = "Y luego ella desapareció, regresando a la oscuridad.\nLa gente miraba hacia arriba con los ojos muy abiertos, observando el cielo que ella había atravesado."
  },
  Stage_7954_Name = {
    Text = "Madera de cedro"
  },
  Stage_7955_Desc = {
    Text = "En el altar de su belleza, estoy dispuesto a ofrecer mis lágrimas, mis suspiros y mi sincero corazón."
  },
  Stage_7955_Name = {Text = "Galatea"},
  Stage_7956_Desc = {
