  },
  Stage_99725_Name = {
    Text = "salón sobre lodo"
  },
  Stage_99726_Desc = {
    Text = "Siempre hemos estado atrapados en la misma balanza compitiendo entre nosotros, pero querido hermano, incluso si no podemos destruirla, podríamos haber elegido saltar de esa balanza."
  },
  Stage_99726_Name = {
    Text = "Escala inclinada"
  },
  Stage_99727_Desc = {
    Text = "Un par de pájaros que se acurrucan mutuamente, nacieron para cantar solo en una jaula."
  },
  Stage_99727_Name = {
    Text = "Aves gemelas"
  },
  Stage_99728_Desc = {
